verifyCmd:
node <<'VERIFYJS'
const n = require('./naturalSort.js');
const S = JSON.stringify;
const eq = (got, want, m) => { if (S(got) !== S(want)) { console.error('FAIL', m, S(got), 'want', S(want)); process.exit(1); } };
eq(n(['file10', 'file2', 'file1']), ['file1', 'file2', 'file10'], 'numeric runs');
eq(n(['a2b', 'a10b', 'a1b']), ['a1b', 'a2b', 'a10b'], 'digits in the middle');
eq(n(['x', 'a', 'm']), ['a', 'm', 'x'], 'plain alpha');
eq(n(['a1', 'a01']), ['a1', 'a01'], 'shorter numeric run first');
eq(n(['B', 'a', 'A', 'b']), ['a', 'A', 'b', 'B'], 'case-insensitive primary, lowercase first on ties');
eq(n(['2', '10', '1']), ['1', '2', '10'], 'pure numbers');
eq(n([]), [], 'empty');
eq(n(['v1.10.0', 'v1.2.0']), ['v1.2.0', 'v1.10.0'], 'version-like');
eq(n(['img12', 'img10', 'img2', 'img1']), ['img1', 'img2', 'img10', 'img12'], 'many');
const input = ['b', 'a'];
n(input);
eq(input, ['b', 'a'], 'must not mutate input');
const dup = n(['same', 'same', 'same']);
eq(dup, ['same', 'same', 'same'], 'stable on equal');
console.log('ok');
VERIFYJS
